SK = 'Sketch a rough graph on the grid. Show every zero (crossing or touching the x-axis), the y-intercept, and the end behavior.'


def sk_grid(lo=-5, hi=5, ylo=-10, yhi=10, ystep=2):
    return blank(x=(lo, hi), y=(ylo, yhi), ystep=ystep,
                 desc='Blank coordinate grid, x from %d to %d (step 1) and y from %d to %d (step %d).' % (lo, hi, ylo, yhi, ystep))


