              sa('List the zeros of -(x + 1)²(x - 2) with multiplicities.', 'Answer:', key='-1 (2), 2 (1)', note='Form required: both.'),
              tf('x(x - 3)² has a zero of multiplicity 2 at x = 3.', key=True, note='Exponent 2.'),
              mc('The zero x = 1 of -(x - 1)³(x + 2) has multiplicity', ['3', '1', '2', '4'], note='Exponent 3.'),
              sa('List the zeros of (x + 2)(x + 1)(x - 1)(x - 3).', 'Answer:', key='-2, -1, 1, 3', note='Form required: all four.'),
